//! WPT `url/percent-encoding.window.js`: its data file
//! `url/resources/percent-encoding.json`, as a table of (input, encoding,
//! expected query, expected fragment).
//!
//! The test loads `resources/percent-encoding.py?encoding=E&value=...`, a
//! document in encoding E holding `<a href="https://doesnotmatter.invalid/?V#V">`,
//! and checks the link's `hash` against the `utf-8` output and its
//! `search` against the output for E. The URL is special (https), so the
//! query is percent-encoded with the special-query percent-encode set in
//! E, and the fragment with the fragment percent-encode set in UTF-8 (URL
//! §4.4, query state and fragment state). The converter checks that the
//! vendored test and server script still say exactly that, so an upstream
//! change to either fails the conversion instead of silently changing
//! what the table means.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &[
    "percent-encoding.json",
    "percent-encoding.py",
    "percent-encoding.window.js",
];

/// Text the test and the server script must contain, verbatim.
const REQUIRED: &[(&str, &str)] = &[
    (
        "percent-encoding.window.js",
        "assert_equals(output.hash, `#${testUnit.output[\"utf-8\"]}`, \"fragment\");",
    ),
    (
        "percent-encoding.window.js",
        "assert_equals(output.search, `?${testUnit.output[encoding]}`, \"query\");",
    ),
    (
        "percent-encoding.window.js",
        "}, `Input ${testUnit.input} with encoding ${encoding}`);",
    ),
    (
        "percent-encoding.py",
        "<a href=\"https://doesnotmatter.invalid/?%s#%s\">test</a>",
    ),
];

struct Case {
    name: String,
    input: Vec<u32>,
    encoding: String,
    query: String,
    fragment: String,
}

/// Convert the suite in `dir` to the body of a Rust source file.
pub fn convert(dir: &Path) -> Result<String, String> {
    for (file, needle) in REQUIRED {
        let path = dir.join(file);
        let text =
            std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        if text.matches(needle).count() != 1 {
            return Err(format!(
                "{file}: expected {needle:?} exactly once; the test changed upstream"
            ));
        }
    }
    let path = dir.join("percent-encoding.json");
    let text = std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
    let json: Value =
        serde_json::from_str(&text).map_err(|e| format!("percent-encoding.json: not JSON: {e}"))?;
    let units = json
        .as_array()
        .ok_or("percent-encoding.json: expected a top-level array")?;
    let mut cases = Vec::new();
    for (k, unit) in units.iter().enumerate() {
        // "Ignore comments"
        if unit.is_string() {
            continue;
        }
        let at = |what: &str| format!("percent-encoding.json: item {k}: {what}");
        let input = unit
            .get("input")
            .and_then(Value::as_str)
            .ok_or_else(|| at("no string \"input\""))?;
        let output = unit
            .get("output")
            .and_then(Value::as_object)
            .ok_or_else(|| at("no object \"output\""))?;
        let fragment = output
            .get("utf-8")
            .and_then(Value::as_str)
            .ok_or_else(|| at("no \"utf-8\" output, which every case's fragment check needs"))?;
        for (encoding, query) in output {
            let query = query
                .as_str()
                .ok_or_else(|| at(&format!("output {encoding:?} is not a string")))?;
            cases.push(Case {
                name: format!("Input {input} with encoding {encoding}"),
                input: input.chars().map(u32::from).collect(),
                encoding: encoding.clone(),
                query: query.to_owned(),
                fragment: fragment.to_owned(),
            });
        }
    }
    if cases.is_empty() {
        return Err("percent-encoding.json: no cases".into());
    }
    render(&cases)
}

fn render(cases: &[Case]) -> Result<String, String> {
    let mut out = String::new();
    out.push_str(
        "// @generated by `cargo xtask testdata` from tests/data/wpt-url-percent-encoding/.\n\
         // Do not edit: `cargo xtask verify` fails if this differs from what the\n\
         // converter (xtask/src/testdata/wpt_url_percent.rs) produces.\n\
         // Source, commit and license: tests/data/wpt-url-percent-encoding/SOURCE.md.\n\
         const WPT: &[Case] = &[\n",
    );
    for c in cases {
        let input: Vec<String> = c.input.iter().map(|u| format!("0x{u:04X}")).collect();
        writeln!(
            out,
            "    Case {{ name: {:?}, input: &[{}], encoding: {:?}, query: {:?}, fragment: {:?} }},",
            c.name,
            input.join(", "),
            c.encoding,
            c.query,
            c.fragment
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}
